const state = {page:'overview', evidence:null, validation:null, result:null, example:null, live:false, filter:'all', query:'', status:'all', selected:null, revision:null, planText:'', labError:''}
const $ = s => document.querySelector(s)
const esc = x => String(x ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))
const num = x => x == null ? '—' : Number(x).toLocaleString('en-US',{maximumFractionDigits:3})
const pct = x => x == null ? '—' : (x*100).toLocaleString('en-US',{maximumFractionDigits:2})+'%'
const pretty = x => esc(JSON.stringify(x,null,2))
const download = (data,name) => { const a=document.createElement('a'), url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})); a.href=url; a.download=name; a.click(); setTimeout(()=>URL.revokeObjectURL(url),1000) }
const statusDescriptions = {
 ok:'The value satisfies the declared contracts. This status does not verify the source measurement.',
 contextual:'The value was assigned from another spatial support, such as a municipality mean assigned to a farm.',
 blocked:'An input contract prevents the calculation.',
 unresolved:'An input was absent at initial computation, or the operation has no defined result.',
 orphan:'An input existed in a previous release and was withdrawn.',
 stale:'A source changed. Dependent outputs require recomputation.'
}
const contractLabels = {qkind:'Quantity kind',unit:'Unit',period:'Period',support:'Spatial support'}
const operationLabels = {sum:'Sum',diff:'Difference',mul:'Product',scale:'Scale',lin:'Linear combination',ratio:'Ratio',broadcast:'Context assignment'}
const badge = s => `<span class="status ${esc(s)}" title="${esc(statusDescriptions[s]||s)}">${esc(s)}</span>`
const metric = (label,value,note) => `<div class="metric"><span class="label">${label}</span><span class="number">${value}</span><span class="note">${note}</span></div>`
const heading = (eyebrow,title,text,actions='') => `<div class="heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="intro">${text}</p></div><div class="actions">${actions}</div></div>`
const card = (title,body,tag='') => `<section class="card"><div class="cardhead"><h2>${title}</h2>${tag?`<span class="tag">${tag}</span>`:''}</div><div class="cardbody">${body}</div></section>`
const bars = (items,unit='Tg C') => {const max=Math.max(...Object.values(items).map(Math.abs),1);return Object.entries(items).map(([k,v])=>`<div class="barrow"><span>${esc(k)}</span><div class="track"><div class="bar ${v<0?'negative':''}" style="width:${Math.abs(v)/max*100}%"></div></div><span class="amount">${num(v)}</span></div>`).join('')+`<div class="sub">Selected contributions (${unit})</div>`}
function overview(){
 const e=state.evidence, x=e.attribution.X1_rondonia_2020_soil_revision
 return heading('Carbon inventory data provenance','Source Revision Evaluation','Compare source releases and trace their effects on inventory values. Select a revision to examine the affected outputs and their sources.',`<button class="btn" data-go="architecture">View architecture ↗</button><button class="btn primary" data-go="revisions">Review source revisions →</button>`)+
 `<div class="grid metrics">${metric('Values in integration process P3',num(e.p3.values),'P3 · soil and land cover · 2017 to 2021')}${metric('Revision scenarios',num(e.revisions.length),'P1, P2 and P3 · replication archive')}${metric('Recall for changed outputs','100%','Observed in the archive scenarios')}${metric('Orphan outputs in the IPCC scenario','5,352','2019 factors with the 2006 region mapping')}</div>`+
 `<div class="grid two">${card('Revision evaluation process',`<p class="sub">The data contract defines meaning and input requirements. The engine compares releases and identifies dependent values.</p><div class="flow"><div class="node"><strong>01</strong>Sources</div><span class="arrow">→</span><div class="node"><strong>02</strong>Contracts</div><span class="arrow">→</span><div class="node"><strong>03</strong>Derivations</div><span class="arrow">→</span><div class="node"><strong>04</strong>Impacts</div></div><div class="row"><span>Input value changed<small>Dependent outputs require recomputation</small></span><span class="status">stale</span></div><div class="row"><span>Input key withdrawn<small>The output retains a record of its former source</small></span>${badge('orphan')}</div><div class="row"><span>Input contract violated<small>The output has no numeric value</small></span>${badge('blocked')}</div>`,'REVISION STATUS')}
 ${card('Attribution by land cover class',`<p class="sub">Rondônia, 2020 · soil collection 3 versus beta 2.1</p>${bars({'Forest':x.by_class_TgC['Forest formation'],'Pasture':x.by_class_TgC.Pasture,'Grassland':x.by_class_TgC.Grassland,'Savanna':x.by_class_TgC['Savanna formation'],'Soybean':x.by_class_TgC.Soybean,'Rivers and lakes':x.by_class_TgC['River and lake']})}<div class="row"><span>Share of the change in ten municipalities</span><strong class="mono">${pct(x.top10_share)}</strong></div>`,'ATTRIBUTION')}</div>`+
 `<div class="feature"><div class="big">+${num(x.change_pct)}%</div><div><span class="tag">RONDÔNIA · 2020</span><h2 style="margin-top:12px">Change in the 2020 soil carbon stock</h2><p>The attribution assigns ${num(x.change_TgC)} Tg C to the land cover classes and municipalities in the calculation. This decomposition does not establish an environmental cause.</p></div><button class="btn" data-go="revisions">View source records ↗</button></div>`+
 `<div class="notice">Evidence source: result files in S1_artC.zip. Evaluation Results identifies the extension tests separately from the archive results.</div>`
}
function revisions(){
 const rows=state.evidence.revisions.filter(r=>state.filter==='all'||r.pipeline===state.filter)
 const selected=rows.find(r=>r.id===state.revision)
 return heading('Source releases and dependencies','Source revisions','Compare the outputs identified for review with the outputs that changed after each source revision. Select a row to inspect its record.',`<button class="btn" id="exportEvidence">Export evidence ↓</button>`)+
 `<div class="toolbar"><label for="pipeline">Integration process</label><select id="pipeline"><option value="all">All</option>${['P1','P2','P3'].map(p=>`<option ${state.filter===p?'selected':''}>${p}</option>`).join('')}</select><span class="tag">EVIDENCE SOURCE · REPLICATION ARCHIVE</span></div><section class="card tablewrap"><table><thead><tr><th>REVISION</th><th>PROCESS</th><th>CHANGED</th><th>FLAGGED</th><th>RECALL</th><th>PRECISION</th><th>ORPHANS</th></tr></thead><tbody>${rows.map(r=>`<tr class="clickrow ${state.revision===r.id?'selected':''}" tabindex="0" data-revision="${esc(r.id)}"><td>${esc(r.name)}</td><td><span class="tag">${r.pipeline}</span></td><td class="num">${num(r.changed)}</td><td class="num">${num(r.flagged)}</td><td class="num">${pct(r.recall)}</td><td class="num">${pct(r.precision)}</td><td class="num">${num(r.orphans)}</td></tr>`).join('')}</tbody></table></section>`+
 (selected?`<div class="detail">${card(esc(selected.name),`<div class="detailgrid"><div>Agreement with full reconstruction<strong>${selected.equal?'Yes':'No'}</strong></div><div>Flagged outputs that did not change<strong>${num(selected.flagged-selected.changed)}</strong></div><div>Source file<strong style="font-size:12px">${esc(selected.source_file)}</strong></div></div><details><summary>Inspect the execution record</summary><pre>${pretty(selected.details)}</pre></details><p class="sub">Agreement with reconstruction checks the two computation paths. It does not independently verify the formulas or the interpretation of source data.</p>`)}</div>`:`<div class="notice">Select a revision to inspect its record. Recall is the share of changed outputs identified by the method. Precision is the share of flagged outputs that changed.</div>`)+
 `<p class="sub">Recall is the share of changed outputs identified by the method. Precision is the share of flagged outputs that changed. Orphans are outputs whose input key was withdrawn after an earlier release.</p><div class="spacer"></div><div class="grid two">${card('Soil carbon stock change by state',bars(state.evidence.attribution.X2_brazil_2020_soil_revision.by_state_TgC),'SOIL REVISION · 2020')}${card('Stock redistribution by land cover class',bars(state.evidence.attribution.X4_brazil_2021_land_cover_revision.by_class_TgC),'LAND COVER REVISION · 2021')}</div>`
}
function lineage(key,values,depth=0,seen=new Set()){
 if(depth>5)return '<div class="sub">The view shows up to five dependency levels. Export the result to inspect the complete record.</div>'
 if(seen.has(key))return ''
 const d=values.find(v=>v.key===key)
 if(!d)return `<div class="lineage">${esc(key)} · input not found</div>`
 const next=new Set(seen); next.add(key)
 return `<div class="lineage" style="margin-left:${depth*12}px">${esc(d.key)} = ${num(d.value)} ${esc(d.contract?.unit)} ${badge(d.status)}<br><span class="muted">${d.operation?esc(operationLabels[d.operation]||d.operation):`source ${esc(d.source)} · version ${esc(d.version)}`}</span></div>`+(d.inputs||[]).slice(0,15).map(k=>lineage(k,values,depth+1,next)).join('')
}
function valuesPage(){
 const result=state.result
 if(!result)return heading('Value provenance','Value inspection','Run an evaluation through the local server or import a result file.')+`<button class="btn primary" data-go="lab">Open evaluation setup</button>`
 let values=result.values
 if(state.query)values=values.filter(v=>v.key.toLowerCase().includes(state.query.toLowerCase()))
 if(state.status!=='all')values=values.filter(v=>v.status===state.status)
 const d=result.values.find(v=>v.key===state.selected)
 return heading('Value provenance','Value inspection','Search for a value key or select a status. Select a row to inspect its contract and source dependencies.',`<button class="btn" id="exportResult">Export result ↓</button>`)+
 `<div class="notice">${result.origin==='imported_result'?'Evidence source: imported result. The interface does not verify the file author or execution environment.':result.origin==='example_execution'?'Evidence source: execution of the demonstration plan. Its values illustrate the method and are not environmental observations.':result.origin==='transfer_execution'?'Evidence source: NOAA transfer test. The input withdrawal is a controlled change to a test copy, not a published NOAA revision.':'Evidence source: local engine execution.'} Plan: ${esc(result.title)}.</div>`+
 `<div class="toolbar"><input type="search" id="valueSearch" aria-label="Search value key" placeholder="Enter a value key" value="${esc(state.query)}"><select id="statusFilter" aria-label="Filter by status"><option value="all">All statuses</option>${['ok','contextual','blocked','unresolved','orphan'].map(s=>`<option ${state.status===s?'selected':''}>${s}</option>`).join('')}</select><span class="sub">${num(values.length)} ${values.length===1?'value':'values'}</span></div>`+
 `<section class="card tablewrap"><table><thead><tr><th>VALUE KEY</th><th>VALUE</th><th>UNIT</th><th>STATUS</th><th>SOURCE OR OPERATION</th></tr></thead><tbody>${values.slice(0,150).map(v=>`<tr tabindex="0" class="clickrow ${v.key===state.selected?'selected':''}" data-value="${esc(v.key)}"><td class="mono">${esc(v.key)}</td><td class="num">${num(v.value)}</td><td>${esc(v.contract?.unit)}</td><td>${badge(v.status)}</td><td>${esc(operationLabels[v.operation]||v.source)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No value matches the search or status filter.</td></tr>'}</tbody></table></section>${values.length>150?'<p class="sub">This view displays up to 150 records. Refine the search or export the result to access all records.</p>':''}`+
 `<details class="statusGuide"><summary>Definitions of value statuses</summary><dl>${Object.entries(statusDescriptions).filter(([key])=>key!=='stale').map(([key,definition])=>`<dt>${esc(key)}</dt><dd>${esc(definition)}</dd>`).join('')}</dl></details>`+
 (d?`<div class="spacer"></div><div class="grid two">${card(esc(d.key),`<div class="detailgrid">${Object.entries(d.contract||{}).map(([k,v])=>`<div>${esc(contractLabels[k]||k)}<strong style="font-size:12px">${esc(v)}</strong></div>`).join('')}</div><p class="sub">${esc(d.reason||'The operation satisfies the declared input requirements.')}</p>`,'CONTRACT')}${card('Source dependency trace',lineage(d.key,result.values),'DEPENDENCIES')}</div>`:'<div class="notice">Select a value to inspect its contract and follow its inputs to their source records.</div>')+
 `<div class="spacer"></div>${card('Revision history',result.revisions.map((r,i)=>`<div class="row"><div>${esc(r.name)}<small>${num(r.metrics.changed)} changed outputs · ${num(r.metrics.new_outputs)} added outputs · recall ${pct(r.metrics.recall)}</small></div><button class="btn" data-history="${i}">Inspect changes</button></div>`).join('')||'<p class="sub">This plan has no source revisions.</p>')}`
}
function lab(){
 return heading('Evaluation configuration','Run an evaluation','Define source data, contracts and operations in a JSON plan. Use the demonstration plan as a template, then execute it through the local server.',`<label class="btn">Import plan<input type="file" accept="application/json,.json" class="upload" id="planFile"></label><label class="btn">Import result<input type="file" accept="application/json,.json" class="upload" id="resultFile"></label>`)+
 `<div class="notice ${state.live?'':'warn'}">${state.live?'Execution is available through the local server. Run evaluation sends the plan below to the Python engine.':'This hosted version supports result inspection and import. To execute a plan, open Iniciar-dashboard.cmd in the project package, then visit http://127.0.0.1:8765 in your browser.'}</div>`+
 `<div class="grid two">${card('Evaluation plan',`<label class="sub" for="plan">JSON plan with contracts and source CSV data</label><div class="spacer"></div><textarea class="editor" id="plan" spellcheck="false">${esc(state.planText)}</textarea><div class="actions"><button class="btn primary" id="runPlan" ${state.live?'':'disabled'}>Run evaluation →</button><button class="btn" id="loadExample">Load demonstration plan</button><button class="btn" id="savePlan">Export plan ↓</button></div>${state.labError?`<p class="errorbox" role="alert">${esc(state.labError)}</p>`:''}`,'JSON + CSV')}${card('Evaluation instructions',`<div class="steps"><div class="step"><div><strong>Specify source data</strong>Provide the source name, version, keys and values. Each CSV requires key and value columns.</div></div><div class="step"><div><strong>Specify the data contract</strong>State the quantity kind, unit, period and spatial support. The engine does not infer column meaning.</div></div><div class="step"><div><strong>Specify the operations</strong>Link each output to its input keys. The plan supports sums, differences, products, scales, ratios and context assignments.</div></div><div class="step"><div><strong>Add a source revision</strong>Provide the complete CSV for the next source version. Declare added output nodes and changes to sum inputs where needed.</div></div><div class="step"><div><strong>Inspect the evaluation result</strong>The result records statuses, contracts, changes and content hashes.</div></div></div><div class="notice">The demonstration plan tests the engine. Its values are separate from the environmental results reported in the article.</div><button class="btn" id="viewExample">Inspect demonstration result ↗</button>`,'DECLARATION FORMAT')}</div>`
}
function architecture(){
 const modules=[['01','Source adapters','Read CSV data with keys, values and contracts. Additional sources use the same declaration schema.'],['02','Version registry','Associate each source with its release identifier and the hash of the received content.'],['03','Contracts','Specify quantity kind, unit, period and spatial support. Each operation checks its input requirements.'],['04','Revision impact engine','Compare keys, values and contracts. Trace dependencies and recompute affected outputs.'],['05','Derivation graph','Record operations and inputs. Add contexts after a revision and reject dependency cycles.'],['06','Audit interface','Expose statuses, reasons and changes as JSON. The dashboard inspects results and the local server executes plans.']]
 return heading('Components and responsibilities','System Architecture','Source declarations specify data meaning and dependencies. The engine applies them to each source revision.')+
 `<div class="architecture">${modules.map(([i,t,d])=>`<section class="module"><span class="index">COMPONENT ${i}</span><h3>${t}</h3><p>${d}</p></section>`).join('')}</div>`+
 `<div class="grid two">${card('Evaluation execution sequence',`<div class="lineage">CSV data and contracts<br>↓<br>Source and version registry<br>↓<br>Operation graph<br>↓<br>Revision → comparison → impact propagation<br>↓<br>Statuses, changes and dependencies<br>↓<br>Local API → dashboard</div>`,'PYTHON + JSON')}${card('Maintainer responsibilities',`<div class="row"><span>Definition of column meaning</span><span class="tag">CONTRACT</span></div><div class="row"><span>Correspondence between category schemes</span><span class="tag">MAPPING</span></div><div class="row"><span>Criteria for accepting a source revision</span><span class="tag">DOMAIN</span></div><div class="row"><span>Attribution rules for each operation</span><span class="tag">MODEL</span></div><p class="sub">A value revision does not by itself indicate an error. The engine reports changes and checks them against the declared requirements.</p>`,'SCOPE')}</div>`+
 `<div class="notice">The replication package retains its original engine and SQL, PROV O and SHACL exports. The extension adds a declaration interface and tests for contexts introduced by source revisions. These exports are not part of the evaluation API.</div>`
}
function evaluation(){
 const v=state.validation, p=v?.prospective
 return heading('Evidence and study scope','Evaluation Results','Review the extension tests and their scope. Archive results and extension results retain separate evidence sources. No participant study has been conducted.',`<button class="btn" id="exportValidation">Export test records ↓</button>`)+
 `<div class="grid metrics">${metric('Engine behavior tests',num(v?.unit_tests?.passed),'Extension test execution')}${metric('Revisions without future context lists',num(p?.steps?.length),'Stock evaluation · V0 → V1 → V2')}${metric('Municipality and year comparisons',num(p?.steps?.reduce((n,s)=>n+s.independent_checks,0)),'Independent arithmetic from CSV extracts')}${metric('Reconstruction mismatches',num(p?.steps?.reduce((n,s)=>n+s.rebuild_mismatches,0)),'Active outputs in each release')}</div>`+
 `<section class="card transferCard"><div class="cardhead"><h2>Transfer test with NOAA data</h2><span class="tag">SOURCES NOT USED IN INTERFACE DEVELOPMENT</span></div><div class="cardbody"><p class="sub">The test integrates two monthly CO2 series from NOAA GML for 2015 to 2023. It compares 135 baseline outputs with Decimal arithmetic, then checks 150 outputs after a year extension. The engine code was unchanged. The changes to source values, units and key availability are controlled perturbations of test copies.</p><div class="detailgrid"><div>Source values<strong>216</strong></div><div>Baseline outputs checked<strong>135</strong></div><div>Outputs after extension<strong>150</strong></div></div><div class="actions"><button class="btn primary" id="viewTransfer">Inspect the source withdrawal test →</button><button class="btn" id="exportTransfer">Export transfer test records ↓</button></div><p class="sub">This case supports transfer to the tested concentration records and operations. It does not establish support for arbitrary sources. World Bank data acquisition timed out and is not counted as a completed transfer test.</p></div></section><div class="spacer"></div>`+
 `${card('Context inclusion after source revisions',`<div class="tablewrap"><table><thead><tr><th>VERSION</th><th>ADDED OUTPUTS</th><th>REWIRED SUMS</th><th>MUNICIPALITY AND YEAR CHECKS</th><th>FAILURES</th></tr></thead><tbody>${(p?.steps||[]).map(s=>`<tr><td>${esc(s.version)}</td><td class="num">${num(s.new_context_outputs)}</td><td class="num">${num(s.rewired_sums)}</td><td class="num">${num(s.independent_checks)}</td><td class="num">${num(s.independent_failures)}</td></tr>`).join('')}</tbody></table></div><p class="sub">The experiment starts with V0 contexts. Each step reads only the release it receives. A separate pandas calculation sums mean × area by municipality and year, without ledger operations. The test covers stocks by class, municipality, state and country. Annual stock differences and attribution are outside this test.</p>`,'EXTENSION TEST EXECUTION')}<div class="spacer"></div>`+
 `<div class="grid two">${card('Behavior test coverage',`<div class="testlist">${(v?.unit_tests?.cases||[]).map(t=>`<div class="testitem"><span>✓</span>${esc(t)}</div>`).join('')}</div>`,'UNIT TESTS')}${card('Evaluation objectives and measures',`<div class="row"><span>Identify revision impacts<small>Recall, precision and added output coverage</small></span><span class="tag">G1</span></div><div class="row"><span>Explain a value change<small>Attribution accuracy and operation coverage</small></span><span class="tag">G2</span></div><div class="row"><span>Add a data source<small>Configuration effort and engine changes</small></span><span class="tag">G3</span></div><div class="row"><span>Support an inventory audit<small>Task time and answer accuracy in a participant study</small></span><span class="tag">G4</span></div><p class="sub">Design Science Research structures the requirements, design decisions and evaluation. The participant study requires a protocol and execution.</p>`,'GOAL QUESTION METRIC · STUDY PLAN')}</div>`+
 `<div class="notice warn">The OpenLineage and Great Expectations comparisons apply to the graph and validation suites used in the study. They do not cover every tool configuration. The 32.3% scenario depends on the factor tables, region mapping and treatment of missing factors as zero.</div>`
}
const pages={overview:chartsPage,revisions,values:valuesPage,lab,architecture,evaluation}
function go(page){state.page=page in pages?page:'overview';location.hash=state.page;render();window.scrollTo(0,0)}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3200)}
function validateResult(r){if(!r||!Array.isArray(r.values)||!Array.isArray(r.revisions)||r.values.some(v=>typeof v.key!=='string'||typeof v.contract!=='object'||!Array.isArray(v.inputs)))throw Error('The file does not match the evaluation result schema.');return r}
function render(){
 $('#page').innerHTML=pages[state.page]()
 bindCharts()
 document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.page===state.page);b.setAttribute('aria-current',b.dataset.page===state.page?'page':'false')})
 document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go))
 const bind=(id,fn)=>{const el=$('#'+id);if(el)el.onclick=fn}
 bind('exportEvidence',()=>download(state.evidence,'evidence.json'))
 bind('exportResult',()=>download(state.result,'audit-result.json'))
 bind('exportValidation',()=>download(state.validation,'validation.json'))
 bind('viewTransfer',async()=>{state.result=await fetch('external-noaa-result.json').then(r=>r.json());state.result.origin='transfer_execution';state.query='concentration_difference|2020|01';state.status='all';state.selected='concentration_difference|2020|01';go('values')})
 bind('exportTransfer',async()=>download(await fetch('transfer-tests.json').then(r=>r.json()),'transfer-tests.json'))

 if($('#pipeline'))$('#pipeline').onchange=e=>{state.filter=e.target.value;render()}
 document.querySelectorAll('[data-revision]').forEach(row=>{const f=()=>{state.revision=row.dataset.revision;render()};row.onclick=f;row.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();f()}}})
 if($('#valueSearch'))$('#valueSearch').oninput=e=>{const el=e.target, pos=el.selectionStart;state.query=el.value;render();$('#valueSearch').focus();$('#valueSearch').setSelectionRange(pos,pos)}
 if($('#statusFilter'))$('#statusFilter').onchange=e=>{state.status=e.target.value;render()}
 document.querySelectorAll('[data-value]').forEach(row=>{const f=()=>{state.selected=row.dataset.value;render()};row.onclick=f;row.onkeydown=e=>{if(e.key==='Enter')f()}})
 document.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>{const r=state.result.revisions[Number(b.dataset.history)];const keys=[...new Set([...Object.keys(r.before),...Object.keys(r.after)])];const diff=keys.filter(k=>JSON.stringify(r.before[k])!==JSON.stringify(r.after[k]));const popup=document.createElement('dialog');popup.innerHTML=`<h2>${esc(r.name)}</h2><p class="sub">Changes in value, status or metadata</p><pre>${pretty(diff.map(k=>({key:k,before:r.before[k],after:r.after[k]})))}</pre><button class="btn">Close</button>`;popup.querySelector('button').onclick=()=>popup.close();popup.onclose=()=>popup.remove();document.body.append(popup);popup.showModal()})
 if($('#plan'))$('#plan').oninput=e=>state.planText=e.target.value
 bind('loadExample',()=>{state.planText=JSON.stringify(state.example,null,2);state.labError='';render()})
 bind('viewExample',async()=>{state.result=await fetch('example-result.json').then(r=>r.json());state.result.origin='example_execution';state.query='';state.status='all';state.selected='total';go('values')})
 bind('savePlan',()=>{try{download(JSON.parse(state.planText),'audit-plan.json')}catch(e){state.labError=e.message;render()}})
 bind('runPlan',async()=>{const b=$('#runPlan');b.disabled=true;b.textContent='Evaluation in progress…';try{const plan=JSON.parse(state.planText);const response=await fetch('/api/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(plan)});const result=await response.json();if(!response.ok)throw Error(result.error||'Evaluation engine error');state.result=validateResult(result);state.selected=null;state.query='';state.status='all';state.labError='';go('values');toast('Evaluation complete')}catch(e){state.labError=e.message;render()}})
 for(const id of ['planFile','resultFile'])if($('#'+id))$('#'+id).onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024)throw Error('Each file must be no larger than 10 MB');const data=JSON.parse(await file.text());if(id==='planFile'){state.planText=JSON.stringify(data,null,2);state.labError='';render()}else{state.result=validateResult(data);state.result.origin='imported_result';state.query='';state.status='all';state.selected=null;go('values')}}catch(error){state.labError=error.message;render()}}
}
async function init(){try{
 const [e,v,example,result]=await Promise.all(['evidence.json','validation.json','example-plan.json','example-result.json'].map(async f=>{const r=await fetch(f);if(!r.ok)throw Error('Could not load '+f);return r.json()}))
 state.charts=await fetch('chart-data.json').then(r=>r.json());state.evidence=e;state.validation=v;state.example=example;state.result=result;state.result.origin='example_execution';state.planText=JSON.stringify(example,null,2)
 try{const r=await fetch('/api/health');if(r.ok){const h=await r.json();state.live=h.execution===true}}catch{}
 $('#runtime').textContent=state.live?'Local execution available':'Archive inspection mode'
 state.page=location.hash.slice(1) in pages?location.hash.slice(1):'overview'
 document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>go(b.dataset.page))
 window.onhashchange=()=>{const page=location.hash.slice(1);if(page in pages&&page!==state.page){state.page=page;render()}}
 render()
 }catch(e){$('#page').innerHTML=`<div class="errorbox">${esc(e.message)}<p>Open the dashboard through the local server or its hosted URL.</p></div>`}}
init()
